import os, sys
HERE = os.path.dirname(os.path.abspath(__file__)); HERE = HERE[:-5] if HERE.endswith(("/W_zh", "/W_en")) else HERE; SK = os.path.abspath(os.path.join(HERE, "..", ".."))
for p in ("view-from-text-v3/tools", "view-from-text-v2/tools", "view-from-text-v2/examples"): sys.path.insert(0, os.path.join(SK, p))
sys.path.insert(0, HERE)
import kp17_pages as KP
from htmlkit import native
JD = os.path.join(HERE, "out")
UNIT_ZH, UNIT_EN = "通用近似定理", "The universal approximation theorem"
TITLE_ZH = "圖型識別 第四章 KP17：通用近似定理（大三）"; TITLE_EN = "Pattern Recognition, Chapter 4, KP17: the universal approximation theorem (undergraduate)"
NOTE_ZH = "教材程度：大學三年級（undergrad）。依講義 lec05-kp17 以 view-from-text-v3 製作：先規劃頁面，每頁以一張原生資訊圖（HTML 設計後轉成原生節點）為主，名詞在同一頁圖內定義。共 10 頁，本單元為自主學習，課堂不講授；講義 §2、§3 與 §5、§6 分別各用一頁或兩頁表達，§5 與 §6 合併為第 5 頁。"
NOTE_EN = "Level: undergraduate (year 3). Made from the lecture lec05-kp17 with view-from-text-v3: pages were planned first and each page is mainly one native infographic (designed in HTML and converted to native nodes), with the terms defined on the same page. 10 pages; this unit is self-study and is not taught in class; sections 5 and 6 of the lecture are merged into page 5."
def fig(n, alt_zh, alt_en):
    return lambda: native(f"kp17_p{n}", f"lec05-kp17-p{n}", KP.W, KP.H, JD, alt_en if os.environ.get("KP_LANG") == "en" else alt_zh)
P = []
NXT = {1: ("多項式的保證", "the polynomial guarantee"), 2: ("龍格現象", "the Runge phenomenon"), 3: ("一層 sigmoid 網路", "the one-layer sigmoid network"), 4: ("相同參數量的公平比與高維", "the equal-parameter comparison and high dimension"), 5: ("誤差下降的速率", "the rates"), 6: ("固定與自適應基底", "fixed and adaptive bases"), 7: ("最佳化的代價", "the cost of optimization"), 8: ("多層更有效（延伸）", "depth helps (extension)"), 9: ("小練習", "the exercises")}
def add(n, lab, title, bridge, notes, alt):
    prev = {2: ("入場券", "the entry ticket"), 3: ("多項式的保證", "the polynomial guarantee"), 4: ("龍格現象", "the Runge phenomenon"), 5: ("sigmoid 網路", "the sigmoid network"), 6: ("公平比與高維", "the fair comparison and high dimension"), 7: ("速率", "the rates"), 8: ("固定與自適應基底", "fixed and adaptive bases"), 9: ("代價", "the cost"), 10: ("多層更有效", "depth helps")}
    zh, en = notes
    if n in prev: zh = f"承接上一頁的「{prev[n][0]}」。" + zh; en = f"Following the previous page on {prev[n][1]}. " + en
    if n == 10: zh += "到這裡這個單元就結束了；之後請接著讀下一單元。"; en += " That ends this unit; next, move on to the next unit."
    if n in NXT: zh += f"接下來的下一頁是「{NXT[n][0]}」。"; en += f" Next, the next page covers {NXT[n][1]}."
    notes = (zh, en)
    P.append(dict(lab=lab, title=title, bridge=bridge, notes=notes, layout="freeform", spec=fig(n, *alt)))
add(1, ("入場券", "Entry ticket"),
    ("多項式、sigmoid 網路、RBF 都是通用近似器；通用近似只是入場券", "Polynomials, sigmoid networks and RBF networks are all universal approximators; that is only the entry ticket"),
    ("前面學了多項式、RBF 與網路。哪一種新座標最後能逼近任何函數？誰又逼近得最快？", "We have seen polynomials, RBF networks and neural networks. Which kind of new coordinates can approximate any function, and which does it fastest?"),
    ("這是 KP17 的第一頁，這個單元是自主學習。先備三件事：多項式分類器與 RBF 網路（KP15、KP16），sigmoid 與一層網路（KP6），以及最大誤差。這一頁先講通用近似定理：節點或階數夠多，就能把緊緻集上的任何連續函數逼近到任意小的誤差；緊緻集是有界又含邊界的範圍，例如區間 0 到 1。三張卡片：多項式有 Weierstrass 定理，誤差大約是 r 的負 2 除以 l 次方；一層 sigmoid 網路也能逼近任何連續函數，誤差大約是 1 除以 k；RBF 網路同樣是通用近似器。三種都成立，所以通用近似是入場券，不是競爭優勢；真正的差別是誤差下降的速度與最佳化難不難。後面的頁面依序用實驗看這兩件事。",
     "This is the first page of KP17, a self-study unit. Prerequisites: polynomial classifiers and RBF networks (KP15, KP16), the sigmoid and one-layer networks (KP6), and the max error. This page states the universal approximation theorem: with enough nodes or degree, any continuous function on a compact set can be approximated to any accuracy; a compact set is a bounded range that includes its boundary, for example the interval 0 to 1. Three cards: polynomials have the Weierstrass theorem and an error of about r to the power minus 2 over l; a one-layer sigmoid network also approximates any continuous function with error about 1 over k; RBF networks are also universal approximators. All three hold, so universal approximation is the entry ticket, not an edge; what really differs is how fast the error falls and how hard the optimization is. The following pages look at those two things with experiments."),
    ("Three approximators: polynomial (fixed basis, error about r^(-2/l)), one-layer sigmoid network (data-adaptive basis, error about 1/k), RBF network (universal approximator); all can approximate any continuous function on a compact set.",) * 2)
add(2, ("多項式的保證", "Polynomial guarantee"),
    ("多項式階數夠高，最大誤差可以任意小：r = 11 時只剩 2.5×10⁻⁷", "A polynomial of high enough degree makes the max error arbitrarily small: only 2.5×10⁻⁷ at r = 11"),
    ("多項式真的能逼近任何連續函數嗎？階數要多高？", "Can a polynomial really approximate any continuous function, and how high must the degree be?"),
    ("這一頁用 Weierstrass 定理看多項式的保證：緊緻集 S 上的連續函數 g，對任何 ε 大於 0，存在 r 階多項式 φ，使得 g 減 φ 的絕對值在 S 上處處小於 ε。最大誤差是目標與近似的差取絕對值，在整個區間取最大者，比平均誤差嚴格。實驗設定是我設計的，可重現：目標 g 等於 sin 2πx 加 0.3x 平方，區間 0 到 1，取 401 個等距點，用最小二乘配 r 階多項式，以 Chebyshev 基底解，避免數值不穩。最大誤差：r = 1 是 0.998，r = 3 是 0.198，r = 5 是 0.0152，r = 7 是 0.000607，r = 9 是 1.5 乘 10 的負 5 次方，r = 11 是 2.5 乘 10 的負 7 次方。r 等於 3 與 4、5 與 6 誤差相同，連成一個台階，每個台階約降一到兩個數量級；原因是令 t 等於 2x 減 1，目標的偶數部分只是 t 平方加常數，r = 2 就配完，之後全靠奇數階。",
     "This page uses the Weierstrass theorem to see the polynomial guarantee: for a continuous g on a compact set S and any ε greater than 0 there is a degree-r polynomial φ with the absolute value of g minus φ below ε everywhere on S. The max error is the largest absolute gap between target and approximation over the whole interval, stricter than the average error. The setup is my own design and reproducible: target g equals sin 2πx plus 0.3 x squared on the interval 0 to 1, 401 equally spaced points, least squares for a degree-r polynomial solved in a Chebyshev basis to avoid numerical instability. Max error: r = 1 gives 0.998, r = 3 gives 0.198, r = 5 gives 0.0152, r = 7 gives 0.000607, r = 9 gives 1.5 times 10 to the minus 5, r = 11 gives 2.5 times 10 to the minus 7. Degrees 3 and 4, and 5 and 6, have equal error and form one step, each step cutting the error by one to two orders of magnitude; the reason is that with t equal to 2x minus 1 the even part of the target is only t squared plus a constant, which r = 2 already fits, and after that only the odd degrees help."),
    ("Max error of the least-squares polynomial against degree r (log scale): r=1 0.998, r=3 0.198, r=5 0.0152, r=7 6.07e-4, r=9 1.5e-5, r=11 2.5e-7; degrees 3-4, 5-6 equal; Weierstrass theorem.",) * 2)
add(3, ("龍格現象", "Runge phenomenon"),
    ("階數越高不一定越好：等距內插 r = 20 的最大誤差高達 59.8，最小二乘只有 0.014", "A higher degree is not always better: interpolation at r = 20 reaches max error 59.8, least squares only 0.014"),
    ("上一頁看到多項式的最大誤差隨階數一路降到 2.5×10⁻⁷。階數越高，擬合就一定越好嗎？", "The last page showed the polynomial guarantee: the max error falls with degree to 2.5×10⁻⁷. Is a higher degree always a better fit?"),
    ("這一頁處理常見迷思：階數越高擬合越好。龍格現象是用等距的點內插，也就是強迫多項式通過每個取樣點，高階多項式在端點附近劇烈擺動，誤差反而變大。實驗設定：目標 1 除以 1 加 25x 平方，區間負 1 到 1，比較兩種作法。圖上紅線是 12 階等距內插，通過 13 個等距點，兩端大幅擺動；藍線是 12 階最小二乘，用 400 個等距點，貼著虛線的目標。最大誤差：階數 4、8、12、16、20 的等距內插分別是 0.438、1.05、3.66、14.4、59.8；最小二乘分別是 0.331、0.15、0.068、0.0308、0.0139。內插越高階越糟，最小二乘降得慢但穩。來源也提醒高階多項式有連乘的數值誤差與自由參數太多的問題，折衷是分段近似。",
     "This page handles a common myth: a higher degree always fits better. The Runge phenomenon: interpolating through equally spaced points, that is forcing the polynomial through every sample, makes a high-degree polynomial swing wildly near the ends so the error grows. Setup: target 1 over 1 plus 25 x squared on the interval minus 1 to 1, comparing two methods. The red curve is the degree-12 interpolation through 13 equally spaced points, swinging hard at both ends; the blue curve is the degree-12 least squares on 400 equally spaced points and hugs the dashed target. Max error for degrees 4, 8, 12, 16, 20: interpolation gives 0.438, 1.05, 3.66, 14.4, 59.8; least squares gives 0.331, 0.15, 0.068, 0.0308, 0.0139. Interpolation gets worse with degree; least squares falls slowly but steadily. The source also warns of numerical error from long products and too many free parameters in high-degree polynomials; the compromise is piecewise approximation."),
    ("Runge function 1/(1+25x^2) on [-1,1]: degree-12 equispaced interpolation swings to about +-3.7 at the ends; least squares tracks the target. Max error r=4,8,12,16,20: interpolation 0.438, 1.05, 3.66, 14.4, 59.8; least squares 0.331, 0.15, 0.068, 0.0308, 0.0139.",) * 2)
add(4, ("sigmoid 網路", "Sigmoid network"),
    ("一層 sigmoid 網路也能逼近：k = 2 就貼近目標，最大誤差 0.0142", "A one-layer sigmoid network also approximates: close to the target already at k = 2, max error 0.0142"),
    ("龍格現象說明高階多項式的等距內插誤差反而變大，最小二乘才穩。換成 sigmoid 網路，一樣能逼近嗎？要幾個節點？", "The Runge phenomenon hurt interpolation, but least squares stayed stable. Does a sigmoid network approximate just as well?"),
    ("這一頁看一層 sigmoid 網路。定理引用 Cybenko、Funahashi、Hornik 等：活化函數是擠壓函數，也就是把任何輸入壓進有限範圍的單調遞增函數，例如 sigmoid，單隱藏層、k 夠大的網路 φ 等於 j 從 1 到 k 的 w 輸出乘 f 括號 w 隱藏轉置 x 的總和再加常數，能把緊緻集上的連續函數逼近到任意誤差。實驗設定是我設計的，可重現：目標與上一頁相同；一維參數是 3k 加 1 個；初始值取隱藏斜率 N(0, 8 平方)、偏置 N(0, 4 平方)、輸出權重 N(0, 1)；用 L-BFGS-B 最小化均方誤差，最多 3000 輪；每個 k 以種子 0 到 7 各訓練一次，取最大誤差最好的一個。最大誤差：k = 1 是 0.819，k = 2 是 0.0142，k = 3 是 0.0056，k = 4 是 0.0058，k = 6 是 0.0045，k = 8 是 0.0011。圖上橘線 k = 1 很粗，青線 k = 2 已經貼近，紫線 k = 4 幾乎重合。",
     "This page looks at the one-layer sigmoid network. The theorem, cited from Cybenko, Funahashi, Hornik and others: when the activation is a squashing function, a monotone increasing function mapping any input into a finite range such as the sigmoid, a single-hidden-layer network with large enough k, namely the sum over j from 1 to k of the output weight times f of the hidden weight transposed times x plus a constant, approximates any continuous function on a compact set to any accuracy. The setup is my own design and reproducible: same target as the previous page; in one dimension there are 3k plus 1 parameters; initial values are hidden slopes N(0, 8 squared), biases N(0, 4 squared), output weights N(0, 1); L-BFGS-B minimizes the mean squared error for at most 3000 iterations; each k is trained once per seed 0 to 7 and the one with the best max error is kept. Max error: k = 1 gives 0.819, k = 2 gives 0.0142, k = 3 gives 0.0056, k = 4 gives 0.0058, k = 6 gives 0.0045, k = 8 gives 0.0011. In the plot the orange curve k = 1 is rough, the teal curve k = 2 is already close, and the violet curve k = 4 almost coincides with the target."),
    ("One-layer sigmoid network phi(x)=sum_j w_j f(w_j x)+w_0 fitted to g=sin2pi x+0.3x^2: k=1,2,4 curves; max error k=1 0.819, k=2 0.0142, k=3 0.0056, k=4 0.0058, k=6 0.0045, k=8 0.0011; 3k+1 parameters.",) * 2)
add(5, ("公平比與高維", "Fair comparison and high dimension"),
    ("維度一升，勝負反轉：一維多項式勝，5 維脊函數網路勝", "Raise the dimension and the winner flips: polynomial in one dimension, network on a 5-D ridge function"),
    ("一層 sigmoid 網路在 k = 2 就貼近目標，最大誤差 0.0142。相同參數量，誰逼近得好？維度升高會怎樣？", "A one-layer sigmoid network is close at k = 2 with max error 0.0142. With the same number of parameters which approximates better, and what changes as the dimension grows?"),
    ("這一頁把一維與高維放在一起比。左邊是一維的公平比：相同參數量，多項式 r 階有 r 加 1 個參數，網路 k 個節點有 3k 加 1 個。7 個參數：r = 6 是 0.0152，k = 2 是 0.0142，差不多；13 個參數：r = 12 是 2.5 乘 10 的負 7 次方，k = 4 是 0.0058；19 個參數：r = 18 是 1.9 乘 10 的負 13 次方，k = 6 是 0.0045。一維平滑目標，多項式反而小得多。右邊是 5 維：輸入維度 l 等於 5，每個分量為標準常態；目標 tanh(2 w 轉置 x)，w 是隨機單位向量，這種只依賴單一方向的函數叫脊函數；3000 個訓練點、2000 個新點，誤差為新點的均方根誤差。多項式 r = 1、2、3、5 的新點誤差是 0.326、0.326、0.222、0.257，參數 6、21、56、252 個；網路 k = 1、2、4 都低於 0.0001，參數 8、15、29 個。註記：這個目標剛好是網路的形狀，是偏袒網路的設計，且常態輸入不是緊緻集；這個例子只說明脊函數在高維對多項式有多不友善。",
     "This page puts one dimension and high dimension side by side. On the left is the one-dimensional fair comparison with the same number of parameters: a degree-r polynomial has r plus 1 parameters and a network with k nodes has 3k plus 1. With 7 parameters: r = 6 gives 0.0152 and k = 2 gives 0.0142, about equal; with 13 parameters: r = 12 gives 2.5 times 10 to the minus 7 and k = 4 gives 0.0058; with 19 parameters: r = 18 gives 1.9 times 10 to the minus 13 and k = 6 gives 0.0045. On a smooth one-dimensional target the polynomial is much smaller. On the right is five dimensions: input dimension l equals 5 with standard normal components; the target is tanh of 2 w transposed x with w a random unit vector, a function that depends on only one direction, called a ridge function; 3000 training points and 2000 new points, error is the root mean square error on the new points. Polynomials r = 1, 2, 3, 5 give new-point errors 0.326, 0.326, 0.222, 0.257 with 6, 21, 56, 252 parameters; networks k = 1, 2, 4 are all below 0.0001 with 8, 15, 29 parameters. Note: this target happens to be the network's own shape, a design that favours the network, and normal inputs are not a compact set; the example only shows how unfriendly a ridge function is to polynomials in high dimension."),
    ("Left, 1-D equal parameters (7,13,19): polynomial 0.0152, 2.5e-7, 1.9e-13 vs network 0.0142, 0.0058, 0.0045. Right, 5-D ridge function new-point error: polynomial r=1,2,3,5 0.326, 0.326, 0.222, 0.257; network k=1,2,4 below 0.0001.",) * 2)
add(6, ("速率", "Rates"),
    ("20 維時，多項式的 r 要乘 1024 倍才能讓誤差減半，網路的 k 只要加倍", "At l = 20 the polynomial's r must grow 1024 times to halve the error; the network's k only doubles"),
    ("公平比裡一維多項式贏，高維卻輸得很慘。為什麼高維時多項式輸得這麼慘？", "In the fair comparison the polynomial won in one dimension but lost badly in high dimension. Why does it lose so badly in high dimension?"),
    ("這一頁給出速率，來源是 Barron 1993：多項式是 O 括號 r 的負 2 除以 l 次方，一層 sigmoid 網路是 O 括號 1 除以 k，輸入維度 l 完全沒出現在式子裡。誤差減半要多少：多項式的 r 要乘 2 的 l 除以 2 次方；網路的 k 永遠只要加倍。圖上藍柱是多項式 r 要乘的倍數：l = 2 是 2，l = 5 是 5.7，l = 10 是 32，l = 20 是 1024；紅柱是網路，永遠是 2。這是最壞情況的漸近速率，不是實測；平滑目標，例如第 2 頁，可快得多，r 與 k 也不是逐參數的比較。",
     "This page gives the rates, from Barron 1993: the polynomial is O of r to the minus 2 over l, the one-layer sigmoid network is O of 1 over k, and the input dimension l does not appear in the formula at all. To halve the error the polynomial's r must be multiplied by 2 to the power l over 2, while the network's k only has to double. In the chart the blue bars are the factor for the polynomial's r: l = 2 gives 2, l = 5 gives 5.7, l = 10 gives 32, l = 20 gives 1024; the red bars are the network and are always 2. This is a worst-case asymptotic rate, not a measurement; smooth targets, such as page 2, can be much faster, and r and k are not a per-parameter comparison."),
    ("Rates: polynomial O(r^(-2/l)), network O(1/k). Factor to halve the error: polynomial 2^(l/2) = 2, 5.7, 32, 1024 for l = 2, 5, 10, 20; network always 2.",) * 2)
add(7, ("固定與自適應基底", "Fixed and adaptive basis"),
    ("網路勝在基底會跟著資料調整：固定基底與資料無關，自適應基底的 w 由資料學出", "The network wins because its basis adapts to the data, unlike a fixed basis"),
    ("速率式顯示高維時多項式的誤差降得慢，網路的 k 只要加倍。這個差別從基底的哪裡來？", "The rates show that in high dimension the polynomial error falls slowly while the network only doubles k. Where in the basis does this difference come from?"),
    ("這一頁解釋為什麼。固定基底像 x1 平方乘 x2 這種，不管資料長什麼樣都一樣的基底函數，多項式就是；左邊的六個函數不隨資料改變。資料自適應基底是 f 括號 w 轉置 x 裡的 w 由資料最佳化出來的基底函數，網路的隱藏節點就是；右邊的三個節點，w 都由資料學出來。來源說所有固定基底的展開，都逃不過誤差下降隨維度變慢的宿命；自適應基底可以免。所以網路在高維才贏，但代價是下一頁的最佳化。",
     "This page explains why. A fixed basis, such as x1 squared times x2, is a basis function that is the same whatever the data look like; polynomials are one. The six functions on the left do not change with the data. A data-adaptive basis is a basis function f of w transposed x whose w is optimized from the data; the hidden nodes of a network are such functions, and on the right all three nodes learn their w from the data. The source says every fixed-basis expansion suffers an error decrease that slows with dimension; an adaptive basis can escape it. So the network wins in high dimension, at the cost of the optimization on the next page."),
    ("Fixed basis (monomials x1, x2, x1^2, x1x2, x2^2, x1^2x2, independent of data) versus data-adaptive basis (f(w^T x) with w learned from data); fixed bases suffer error that slows with dimension.",) * 2)
add(8, ("代價", "The cost"),
    ("代價是最佳化變成非線性：k = 2 的 8 次嘗試，5 次低於 0.1，3 次卡在 0.82 附近", "The cost is nonlinear optimization: of eight tries at k = 2, five fall below 0.1 and three get stuck near 0.82"),
    ("資料自適應基底讓網路跟著資料調整，固定基底做不到。自適應基底的代價是什麼？", "A data-adaptive basis lets the network follow the data while a fixed basis cannot. What is the price of an adaptive basis?"),
    ("這一頁是代價。固定基底的係數是線性最小二乘，一步解出；網路的權重要用迭代法找，結果看起點，也就是最佳化從線性變成非線性。實驗：同一份資料、k = 2、8 個隨機起點，種子 0 到 7，最大誤差分別是 0.061、0.015、0.82、0.82、0.82、0.023、0.042、0.014，也就是 5 個低於 0.1，3 個卡在 0.82 附近（程式計算）。紫柱是 k = 3 的同樣 8 個起點，也有卡在 0.82 與 0.999 的起點。所以實務上要多試幾個起點，取最好的。",
     "This page is the cost. Fixed-basis coefficients come from linear least squares solved in one step; network weights have to be found iteratively and the result depends on the start, that is, the optimization changes from linear to nonlinear. Experiment: same data, k = 2, 8 random starts, seeds 0 to 7, with max errors 0.061, 0.015, 0.82, 0.82, 0.82, 0.023, 0.042, 0.014, so five fall below 0.1 and three get stuck near 0.82 (program computed). The violet bars are the same eight starts at k = 3, which also has starts stuck near 0.82 and at 0.999. So in practice you try several starts and keep the best."),
    ("Max error of 8 random starts (seeds 0-7): k=2: 0.061, 0.015, 0.82, 0.82, 0.82, 0.023, 0.042, 0.014 (five below 0.1, three stuck near 0.82); k=3: 0.006, 0.019, 0.816, 0.017, 0.023, 0.026, 0.823, 0.999.",) * 2)
add(9, ("多層更有效", "Depth helps"),
    ("每多一層，段數加倍：n = 10 時，深網路 20 個節點，單隱藏層要 1023 個", "Each extra layer doubles the segments: at n = 10 a deep network needs 20 nodes, one hidden layer needs 1023"),
    ("最佳化變成非線性，k = 2 的 8 個隨機起點有 3 個卡在 0.82。再多疊幾層，會更省節點嗎？", "Optimization became nonlinear and three of eight random starts at k = 2 got stuck near 0.82. Does stacking more layers save nodes?"),
    ("這是延伸：多層更有效。帽函數 h(x) 等於 2 乘 min(x, 1 減 x)，用 2 個 ReLU 節點做得出；ReLU 是 max(0, x) 這種折線型活化函數，原理與 sigmoid 相同。疊 n 層得 2 的 n 次方段直線，程式數過 n = 1 到 4：2、4、8、16 段。深的網路需要 2n 個節點；只有一個隱藏層的 ReLU 網路最多 k 加 1 段，要 2 的 n 次方減 1 個節點。n = 3、6、10 時，深網路 6、12、20 個節點，單隱藏層 7、63、1023 個。來源說用多於一個隱藏層，可能以較少的神經元達到同樣的精度。",
     "This is the extension: depth helps. The hat function h of x equals 2 times the minimum of x and 1 minus x, and two ReLU nodes make it; ReLU is a piecewise-linear activation max(0, x), and the principle is the same as for the sigmoid. Stacking n layers gives 2 to the power n line segments, counted by program for n = 1 to 4: 2, 4, 8, 16 segments. A deep network needs 2n nodes; a ReLU network with a single hidden layer has at most k plus 1 segments, so it needs 2 to the power n minus 1 nodes. For n = 3, 6, 10 the deep network needs 6, 12, 20 nodes and a single hidden layer needs 7, 63, 1023. The source says that using more than one hidden layer can reach the same accuracy with fewer neurons."),
    ("Hat function stacked n=1,2,3 layers gives 2, 4, 8 segments; deep network 2n nodes versus single hidden layer 2^n-1 nodes: n=3: 6 vs 7, n=6: 12 vs 63, n=10: 20 vs 1023.",) * 2)
add(10, ("小練習", "Exercises"),
    ("兩題小練習：誤差減半要乘 16 倍；5 層帽函數有 32 段，深網路 10 個節點", "Two exercises: halving the error takes 16 times; five hat layers give 32 segments"),
    ("帽函數每多一層，段數加倍，深網路只要 2n 個節點。用速率與段數的公式算一次，答案是多少？", "Each extra layer of the hat function doubles the segments and a deep network needs only 2n nodes. What do the rate formula and the segment count give?"),
    ("兩題小練習。題 1：l 等於 8，多項式誤差約為 r 的負 2 除以 l 次方，誤差減半，r 要乘多少倍？減半，r 要乘 2 的 8 除以 2 次方，也就是 2 的 4 次方等於 16 倍；這是漸近式，不是精確的實測。題 2：5 層帽函數有幾段？深網路要幾個 ReLU 節點、單隱藏層要幾個？5 層有 2 的 5 次方等於 32 段；深網路 2 乘 5 等於 10 個節點；單隱藏層 2 的 5 次方減 1 等於 31 個。核對：32 段要 31 個折點，單層 k 個節點最多 k 個折點，所以 k 至少 31。",
     "Two exercises. Q1: l equals 8 and the polynomial error is about r to the minus 2 over l; by what factor must r grow to halve the error? To halve it, r must be multiplied by 2 to the power 8 over 2, that is 2 to the 4th, which is 16 times; this is an asymptotic formula, not an exact measurement. Q2: how many segments does a five-layer hat function have, and how many ReLU nodes for a deep network and for a single hidden layer? Five layers give 2 to the 5th, which is 32 segments; a deep network needs 2 times 5 equals 10 nodes; a single hidden layer needs 2 to the 5th minus 1, which is 31. Check: 32 segments need 31 kinks and k nodes make at most k kinks, so k is at least 31."),
    ("Exercise 1: l=8, halving the error multiplies r by 2^(8/2)=16. Exercise 2: five hat layers give 2^5=32 segments; deep network 10 nodes; single hidden layer 2^5-1=31 nodes.",) * 2)
PAGES = P
